INSERT INTO `quest_template_locale` (`ID`, `locale`, `LogTitle`, `LogDescription`, `QuestDescription`, `AreaDescription`, `PortraitGiverText`, `PortraitGiverName`, `PortraitTurnInText`, `PortraitTurnInName`, `QuestCompletionLog`, `VerifiedBuild`) VALUES
(49474, 'zhTW', '詛咒裂片', '把詛咒裂片帶去破碎群島給達拉然的秘匠維里迪。', '<你看到一塊不斷變換色彩的奇異金屬裂片。你一碰到它，裂片的一端就開始膨脹，然後漸漸融化。液體滴落地上的時候，你聽到嘶嘶聲，接著就有一股惡臭撲鼻而來。$b$b達拉然的金屬工匠或許會知道這是什麼東西。>', '', '', '', '', '', '', 25549),
(49473, 'zhTW', '泰坦級的研究', '帶$1oa個覺醒精華給秘匠維里迪。', '這個物質的反應程度一天比一天來得強。這樣下去就算打贏燃燒軍團，也可能失去對我們來說更加寶貴的東西。\n\n或許這是將來會出現巨大動盪的預兆？世界會面臨什麼樣的命運呢，$n？\n\n我這輩子都在熔爐中尋找答案，也打算繼續這麼做。不過，你要的答案，可能藏在別的地方。', '', '', '', '', '', '', 25549),
(49472, 'zhTW', '泰坦級的研究', '帶$1oa個覺醒精華給秘匠維里迪。', '就算伊利丹推了命運之手一把，但讓阿古斯這麼靠近艾澤拉斯，卻加快了夜井崩塌所引發的反應。\n\n我認為燃燒軍團在阿古斯的行動，會讓我們多年來在不知情的狀況下所汲取的力量更不穩定。\n\n這顯然還需要再深入研究。', '', '', '', '', '', '', 25549),
(49445, 'zhTW', '交易原始精華', '', '', '', '', '', '', '', '', 25549),
(49293, 'zhTW', '突襲侵略點', '完成3個一般侵略點。', '我們絕對不能把任何一個世界拱手讓給燃燒軍團。在侵略點持續進攻，把燃燒軍團踏個粉碎。', '', '', '', '', '', '', 25549),
(49224, 'zhTW', '虛空之光熔爐', '使用虛空之光熔爐，將虛空之光強化效果注入一個聖物中。', '熔爐因為充滿能量而嗡嗡作響。再過不久我們的武器就會比星辰還燦爛！\n\n一定要擁有這種力量，才有可能在這裡擊敗燃燒軍團。\n\n$n，這段時間以來，你承受了莫大的挫折和磨難，熔爐就交給你啟動吧，這是屬於你的榮耀。', '', '', '', '', '', '', 25549),
(49196, 'zhTW', '大型侵略點：深淵領主邪莫斯', '', '', '', '', '', '', '', '', 25549),
(49195, 'zhTW', '大型侵略點：歐庫雷洛斯', '', '', '', '', '', '', '', '', 25549),
(49143, 'zhTW', '聖光之母精華', '收集$1oa個餘存聖光。', '$n，現在是關鍵時刻。我們絕對不能在這個時候灰心喪志。\n\n瑟拉雖然已經逝去，但我能感覺到她還在我們身旁。原本在她心中閃耀的聖光仍然可以為我們帶來力量。\n\n失去瑟拉讓圖拉揚受到莫大的打擊。我會想辦法減輕他的痛苦。你先去收集至高那魯的餘存聖光吧。', '', '', '', '', '', '', 25549),
(49135, 'zhTW', '阿古斯之心', '在傳奇難度的安托洛斯，燃燒王座中，從阿格拉瑪身上獲得4個黑暗泰坦符印。', '哈圖恩告訴我，阿古斯當初淪陷以後，薩格拉斯在阿古斯的核心建造了黑暗神殿。因為黑暗泰坦只讓最忠誠的心腹擁有可以進入神殿的符印，所以關於神殿我們所知不多。\n\n如果我們能拿到符印，就能把符印裝到梵迪卡爾上，我們的部隊就能直接朝阿古斯腐惡的核心進攻。', '', '', '', '', '', '', 25549),
(49134, 'zhTW', '阿古斯之心', '在英雄難度的安托洛斯，燃燒王座中，從阿格拉瑪身上獲得4個黑暗泰坦符印。', '哈圖恩告訴我，阿古斯當初淪陷以後，薩格拉斯在阿古斯的核心建造了黑暗神殿。因為黑暗泰坦只讓最忠誠的心腹擁有可以進入神殿的符印，所以關於神殿我們所知不多。\n\n如果我們能拿到符印，就能把符印裝到梵迪卡爾上，我們的部隊就能直接朝阿古斯腐惡的核心進攻。', '', '', '', '', '', '', 25549),
(49133, 'zhTW', '阿古斯之心', '在普通難度的安托洛斯，燃燒王座中，從阿格拉瑪身上獲得4個黑暗泰坦符印。', '哈圖恩告訴我，阿古斯當初淪陷以後，薩格拉斯在阿古斯的核心建造了黑暗神殿。因為黑暗泰坦只讓最忠誠的心腹擁有可以進入神殿的符印，所以關於神殿我們所知不多。\n\n如果我們能拿到符印，就能把符印裝到梵迪卡爾上，我們的部隊就能直接朝阿古斯腐惡的核心進攻。', '', '', '', '', '', '', 25549),
(49099, 'zhTW', '侵略點：波尼克', '', '', '', '', '', '', '', '', 25549),
(49098, 'zhTW', '侵略點：申迦爾', '', '', '', '', '', '', '', '', 25549),
(49097, 'zhTW', '侵略點：薩恩古瓦', '', '', '', '', '', '', '', '', 25549),
(49096, 'zhTW', '侵略點：奈格塔', '', '', '', '', '', '', '', '', 25549),
(49091, 'zhTW', '侵略點：衛爾', '', '', '', '', '', '', '', '', 25549),
(49077, 'zhTW', '回憶時刻', '把伊利丹的水晶交給他最親近的人，然後再帶去影響他最深的地方。', '<水晶對你發出呼喚，散發著巫士魔法的能量。\n\n握在手中的時候，你聽見了迴盪在其中的訊息，訴說著伊利丹託付給你的任務。>', '', '', '', '', '', '', 25549),
(49076, 'zhTW', '黑暗通道', '在傳奇難度的安托洛斯，燃燒王座中，從『獵魂者』伊莫納爾身上獲得4個通行符文。', '雖然阿古斯的核心不斷發出危險的能量，獵魂者還是可以在燃燒王座來去自如。根據我們的偵查報告，他的船艦會利用惡魔符文通往聖禦魔城。\n\n如果我們能拿到那些惡魔符文，梵迪卡爾就可以走同樣的路線，這樣一來就能替我們的部隊省下寶貴的時間。', '', '', '', '', '', '', 25549),
(49075, 'zhTW', '黑暗通道', '在英雄難度的安托洛斯，燃燒王座中，從『獵魂者』伊莫納爾身上獲得4個通行符文。', '雖然阿古斯的核心不斷發出危險的能量，獵魂者還是可以在燃燒王座來去自如。根據我們的偵查報告，他的船艦會利用惡魔符文通往聖禦魔城。\n\n如果我們能拿到那些惡魔符文，梵迪卡爾就可以走同樣的路線，這樣一來就能替我們的部隊省下寶貴的時間。', '', '', '', '', '', '', 25549),
(49057, 'zhTW', '迷你派拉西斯', '', '', '', '', '', '', '', '', 25549),
(49051, 'zhTW', '阿古斯腐化之血', '', '', '', '', '', '', '', '', 25549),
(49048, 'zhTW', '斯諾茲', '', '', '', '', '', '', '', '', 25549),
(49042, 'zhTW', '穢爪', '', '', '', '', '', '', '', '', 25549),
(49032, 'zhTW', '黑暗通道', '在普通難度的安托洛斯，燃燒王座中，從『獵魂者』伊莫納爾身上獲得4個通行符文。', '雖然阿古斯的核心不斷發出危險的能量，獵魂者還是可以在燃燒王座來去自如。根據我們的偵查報告，他的船艦會利用惡魔符文通往聖禦魔城。\n\n如果我們能拿到那些惡魔符文，梵迪卡爾就可以走同樣的路線，這樣一來就能替我們的部隊省下寶貴的時間。', '', '', '', '', '', '', 25549),
(49015, 'zhTW', '泰坦之死', '在安托洛斯，燃燒王座擊倒阿古斯的靈魂。', '我沒辦法形容我的傷痛有多深，我的憤怒有多強烈。薩格拉斯做的那些事…$b$b我的家園阿古斯擁有泰坦靈魂，但這個靈魂已經被扭曲、腐化，無法拯救了。它現在被燃燒軍團當成燃料，不斷生產永無止盡的大軍。$b$b我們必須完成不可能的任務…殺進安托洛斯，切斷燃燒軍團和世界之魂之間的連結。$b$b$n，拜託你了，別讓阿古斯繼續受苦，停止它的痛楚。只要消滅阿古斯的黑暗之心，我們就能擊敗燃燒軍團…就能淨化世界之魂。', '', '', '', '', '', '', 25549),
(49014, 'zhTW', '燃燒王座', '在安托洛斯荒原上方與大工藝師羅穆爾交談，開啟通往安托洛斯的道路。', '$n，就是現在了，準備攻擊安托洛斯。我們之所以努力奮鬥，我們的家人和朋友所犧牲的一切，都是為了這一刻。$b$b我會用聖光審判轟炸邪惡的堡壘牆壁，直接攻擊它們的權力中樞。我們一定能消滅燃燒軍團。$b$b你做了這麼多，這個榮耀的任務就交給你吧。跟羅穆爾交談，完成我們的任務。', '', '', '', '', '', '', 25549),
(49007, 'zhTW', '指揮官出現了！', '使用維夏克斯的傳送門。', '<這個設備發出嗡嗡聲開始運作。你現在可以前往安托洛斯荒原找小隊指揮官維夏克斯了。>', '', '', '', '', '', '', 25549),
(48983, 'zhTW', '礦工行規', '', '', '', '', '', '', '', '', 25549),
(48982, 'zhTW', '侵略點：奧里諾', '', '', '', '', '', '', '', '', 25549),
(48977, 'zhTW', '聖光軍團的補給品', '在梵迪卡爾上與復仇者潔拉娜交談，以取得你的獎勵。', '勇士，archenon poros (祝你好運)。\n\n聖光軍團想感謝你在阿古斯幫忙對抗燃燒軍團。\n\n我們非常感激，請接受這些補給品。因為你一直支持聖光軍團，我們才能繼續努力，總有一天我們會能永遠消滅燃燒軍團的。', '', '', '', '', '', '', 25549),
(48976, 'zhTW', '阿古斯守望的補給品', '在梵迪卡爾與『崇敬者』托爾蘭交談。', '$ct，因為你努力不懈，讓我們的部隊能搶先找到資源，使資源不致落入燃燒軍團手中。\n\n只要你繼續幫助我們，我們就能給你更多資源。', '', '', '', '', '', '', 25549),
(48974, 'zhTW', '聖光軍團典範', '在梵迪卡爾上與復仇者潔拉娜交談。', '聖光軍團的盟友對你鼎力相助十分感激，想獎勵你，請你過去一趟。', '', '', '', '', '', '', 25549),
(48973, 'zhTW', '阿古斯守望典範', '在梵迪卡爾與『崇敬者』托爾蘭交談。', '阿古斯守望的盟友對你鼎力相助十分感激，想獎勵你，請你過去一趟。', '', '', '', '', '', '', 25549),
(48958, 'zhTW', '中止儀式', '', '', '', '', '', '', '', '', 25549),
(48954, 'zhTW', '泰坦之血', '把『滅界者』阿古斯之血帶去達拉然交給卡德加。', '<阿古斯倒下了，泰坦之血在你眼前滴落，凝結成完美無瑕的寶石。你把寶石握在手中，感覺到難以想像的力量…卻也伴隨著苦痛和哀傷。\n\n這是原本不可能獲勝的最後戰役。這是原本不可能達到的成就。然而就像其他所有勝利的果實一樣，代價實在太大了。\n\n你馬上就明白該找誰分享戰果。>', '', '', '', '', '', '', 25549),
(48953, 'zhTW', '三傑議會之座：黑暗呼喚者', '', '', '', '', '', '', '', '', 25549),
(48952, 'zhTW', '賞根骨頭', '', '', '', '', '', '', '', '', 25549),
(48951, 'zhTW', '三傑議會之座：虛無獸', '', '', '', '', '', '', '', '', 25549),
(48937, 'zhTW', '製造虛空行者傳送門產生器', '', '', '', '', '', '', '', '', 25549),
(48931, 'zhTW', '巨怪甦醒', '', '', '', '', '', '', '', '', 25549),
(48929, 'zhTW', '評估敵情', '與圖拉揚交談。', '要是你的大主教知道我們沒有足夠的資源進攻安托洛斯，一定會非常困擾。我想他很難接受偉大的聖光軍團也會有無能為力的時候。\n\n不過他的驕傲與我無關。在他擬定新策略的時候，我只管殺我的惡魔。\n\n去吧。在我們獲得最後勝利之前，還有很多事要完成。', '', '', '', '', '', '', 25549),
(48912, 'zhTW', '為安托洛斯戰役提供補給品', '完成10個侵略點任務。', '燃燒的遠征需要大量物資，這些物資來自於它們佔領的世界。穿過燃燒軍團傳送門，消滅惡魔，然後截斷物資輸送。別讓它們的戰爭機器繼續運作。', '', '', '', '', '', '', 25549),
(48911, 'zhTW', '虛無療法', '收集100枚濃縮虛無碎片。', '所有受到暗影影響的生物在死後都會留下虛無的痕跡。如果你在城市旅行中收集到虛無，可以來找我。我會淨化虛無，製造出更純粹的型態。\n\n這樣就可以救更多族人了。', '', '', '', '', '', '', 25549),
(48910, 'zhTW', '資助克庫恩', '收集$1oa大廳資源。', '我們在這個荒涼的地方活得很辛苦，這裡物資缺乏，族人時時刻刻都得尋找物資，才能勉強存活。如果能有更多物資，我就可以派遣另一個山脊行者協助你。\n\n外界者，你覺得這個提議如何？', '', '', '', '', '', '', 25549),
(48875, 'zhTW', '攪一攪', '', '', '', '', '', '', '', '', 25549),
(48867, 'zhTW', '首席鍊金師孟庫勒斯', '', '', '', '', '', '', '', '', 25549),
(48864, 'zhTW', '破碎者鑄造師', '找到鑄造師蓋爾。', '$C，這可能是三傑軍械庫鑰匙的一部分。我們當初逃離阿古斯時，把軍械庫封起來了。上次看到鑰匙是在我的副手雅塔拉手中，那是好久以前的事…\n\n我沒辦法確定是不是就是這把鑰匙，但有個人應該可以。當初做鑰匙的鑄造師叫蓋爾。聽說克庫恩有破碎者活下來了，也許蓋爾還活著。', '', '', '', '', '', '', 25549),
(48836, 'zhTW', '看守者埃瓦爾', '', '', '', '', '', '', '', '', 25549),
(48835, 'zhTW', '馴犬者克拉剋斯', '', '', '', '', '', '', '', '', 25549),
(48834, 'zhTW', '裂界者斯庫歐', '', '', '', '', '', '', '', '', 25549),
(48833, 'zhTW', '完成儀式', '', '', '', '', '', '', '', '', 25549),
(48831, 'zhTW', '指揮官泰克斯拉茲', '', '', '', '', '', '', '', '', 25549),
(48830, 'zhTW', '審判官維洛斯', '', '', '', '', '', '', '', '', 25549),
(48829, 'zhTW', '憤怒領主亞瑞茲', '', '', '', '', '', '', '', '', 25549),
(48828, 'zhTW', '撒卡爾中尉', '', '', '', '', '', '', '', '', 25549),
(48827, 'zhTW', '瓦加', '', '', '', '', '', '', '', '', 25549),
(48803, 'zhTW', '重鑄通往過去的鑰匙', '等蓋爾重鑄軍械庫鑰匙。', '軍械庫鑰匙碎片都收集好了，突叢石應該可以提供足夠的能量來重鑄鑰匙。$b$b應該不需要太久…大概…或許能成功吧。我已經太久沒碰這些東西了！', '', '', '', '', '', '', 25549),
(48799, 'zhTW', '破碎世界的資源', '從阿古斯的侵略點、稀有生物或藏寶箱獲得$1oa個純淨阿古岩。', '$n，這片荒原有一種稀有而珍貴的資源。$b$b阿古斯原本有很多阿古岩。阿古岩的魔法特性讓埃雷達爾變得富足強盛。這種力量由我們使用，一定比落入燃燒軍團手中好。$b$b勇士，去收集純淨阿古岩。這些阿古岩能幫助我們完成使命。', '', '', '', '', '', '', 25549),
(48783, 'zhTW', '出乎意料', '', '', '', '', '', '', '', '', 25549),
(48780, 'zhTW', '其勢如劍', '', '', '', '', '', '', '', '', 25549),
(48777, 'zhTW', '惡魔巢穴', '', '', '', '', '', '', '', '', 25549),
(48738, 'zhTW', '『眾相一體』祖爾潭', '', '', '', '', '', '', '', '', 25549),
(48735, 'zhTW', '監督者伊索娜', '', '', '', '', '', '', '', '', 25549),
(48734, 'zhTW', '監督者伊貝塔', '', '', '', '', '', '', '', '', 25549),
(48733, 'zhTW', '傑頂摔角冠軍沃魯斯克', '', '', '', '', '', '', '', '', 25549),
(48729, 'zhTW', '亞泰克森', '', '', '', '', '', '', '', '', 25549),
(48727, 'zhTW', '法魯克隊長', '', '', '', '', '', '', '', '', 25549),
(48725, 'zhTW', '毒尾天鰭魟魚', '', '', '', '', '', '', '', '', 25549),
(48701, 'zhTW', '嗜血的巴魯特', '', '', '', '', '', '', '', '', 25549),
(48691, 'zhTW', '靈魂之縛', '', '', '', '', '', '', '', '', 25549),
(48688, 'zhTW', '', '', '', '', '', '', '', '', '', 25549),
(48686, 'zhTW', '', '', '', '', '', '', '', '', '', 25549),
(48668, 'zhTW', '光鑄信標：城鎮中心', '啟動梵迪卡爾信標。', '你好，朋友！$b$b法芮雅隊長派我們來防守這個區域。我們正打算召喚信標回梵迪卡爾去回報。$b$b如果你願意幫我們完成任務，這會是我們莫大的榮幸。$b$b你只需要輕觸就能啟動信標，大工藝師會完成接下來的步驟。', '', '', '', '', '', '', 25549),
(48662, 'zhTW', '導火線', '', '', '', '', '', '', '', '', 25549),
(48654, 'zhTW', '在歐羅納爾遺跡下', '在歐羅納爾遺跡底下與克庫交談。', '我們在歐羅納爾遺跡底下找到的克庫不想離開。$n，你可以跟他談談嗎？勸他到梵迪卡爾來吧。', '', '', '', '', '', '', 25549),
(48642, 'zhTW', '阿古斯守望', '在阿古斯完成任何4個阿古斯守望世界任務。', '完成4個世界任務以協助阿古斯守望。', '', '', '', '', '', '到阿古斯的梵迪卡爾找『崇敬者』托爾蘭。', 25549),
(48641, 'zhTW', '軍團之殞部隊', '在破碎海岸完成4個世界任務。', '完成4個世界任務來協助軍團之殞。', '', '', '', '', '', '回破碎海岸找指揮官錢柏。', 25549),
(48640, 'zhTW', '不朽小隊', '', '', '', '', '', '', '', '', 25549),
(48639, 'zhTW', '聖光軍團', '在阿古斯完成任何4個聖光軍團世界任務。', '完成4個世界任務來協助聖光軍團。', '', '', '', '', '', '到阿古斯的梵迪卡爾找復仇者潔拉娜。', 25549),
(48637, 'zhTW', '淨化之火', '', '', '', '', '', '', '', '', 25549),
(48636, 'zhTW', '為安托洛斯戰役提供物資', '完成10個侵略點任務。', '燃燒的遠征需要大量物資，這些物資來自於它們佔領的世界。穿過燃燒軍團傳送門，消滅惡魔，然後截斷物資輸送。別讓它們的戰爭機器繼續運作。', '', '', '', '', '', '', 25549),
(48635, 'zhTW', '進一步的虛無療法', '收集100枚濃縮虛無碎片。', '所有受到暗影影響的生物在死後都會留下虛無的痕跡。如果你在城市中收集到虛無的話，可以來找我。我會加以蒸餾，產生更純粹的虛無。\n\n這樣就可以救更多族人了。', '', '', '', '', '', '', 25549),
(48634, 'zhTW', '繼續資助克庫恩', '收集$1oa大廳資源。', '我們在這個荒涼的地方活得很辛苦，這裡物資缺乏，族人時時刻刻都得尋找物資，才能勉強存活。如果能有更多物資，我就可以派遣另一個山脊行者協助你。\n\n外界者，你覺得這個提議如何？', '', '', '', '', '', '', 25549),
(48605, 'zhTW', '指揮官之死', '完成一場大型侵略點事件。', '有個燃燒軍團精英正在侵略點內，無人保護！追查它的下落，並在它重回阿古斯戰場之前消滅它。', '', '', '', '', '', '', 25549),
(48601, 'zhTW', '魔火四射', '使用偵察地圖，完成「攻擊魔火軍械庫」任務。', '在魔獵場那邊，有幾座窄窄的石橋把魔火軍械庫和燃燒裂口連接起來。聖光軍團會對付燃燒軍團的援軍，你們就去處理軍械庫吧。\n\n務必盡快完成任務。', '', '', '', '', '', '', 25549),
(48600, 'zhTW', '扭轉戰局', '將6位勇士的物品等級升到950。', '那些安托洛斯的惡魔身上帶著魔火軍械庫的武器。我們必須想辦法切斷武器來源。你們$c願意和聖光軍團一起戰鬥嗎？\n\n發動攻擊前，我們必須先準備物資。我的鍛造師會幫你的手下準備強大的裝備。要拿下魔火軍械庫，肯定會是場硬仗。', '', '', '', '', '', '', 25549),
(48592, 'zhTW', '守住尖塔', '', '', '', '', '', '', '', '', 25549),
(48560, 'zhTW', '獻上暗影', '將暗影精華注入虛空之光熔爐。', '$n，你感覺到了嗎？這精華中的黑暗力量是如此的強大。\n\n以前我可能會唾棄這種力量，甚至對這種力量視而不見。但經過漫長的抗戰以後，我們現在明白：光明與黑暗必須共存。\n\n也許虛空之光熔爐也需要這種平衡。只有這樣，我們才能獲得擊敗燃燒軍團所需要的優勢。\n\n勇士，把精華注入熔爐中吧。只有這樣，你的武器才能發揮真正的潛能。', '', '', '', '', '', '', 25549),
(48559, 'zhTW', '獻上聖光', '將聖光精華注入虛空之光熔爐。', '我感覺到了。瑟拉內心的高貴本質。她日復一日對抗燃燒軍團，永不懈怠。我們要把她的精神傳承下去。\n\n我們在打造梵迪卡爾時，為了要利用阿古斯的強大力量，製造了虛空之光熔爐。瑟拉的精華或許正是釋放熔爐潛能的關鍵。\n\n但只有聖光的力量是不夠的。沒有平衡，力量就無法調和。\n\n勇士，把精華注入虛空之光熔爐中。如果要阻止燃燒的遠征，就必須這麼做才能開始獲得力量。', '', '', '', '', '', '', 25549),
(48544, 'zhTW', '駕！駕！', '回克庫營地找哈圖恩族長。', '$n，謝謝你，剩下的工作就交給馴獸師吧。如果你願意再幫個忙，能不能請你帶個訊息給哈圖恩族長？我想讓他知道灰石林恢復安全了。相信他一定會獎勵你的。\n\n我可以把最快的蹬崖塔巴克借給你。記得快離開灰石林時，左右兩邊都要看看。有一個超大型燃燒軍團消滅者在那邊巡邏。祝你好運。', '', '', '', '', '', '', 25549),
(48542, 'zhTW', '反擊', '在灰石林殺死$1oa個埃雷達爾祭儀師和薩菈扎德女士。', '卷軸記載的黑暗法術會從附近的克庫身上盜取靈魂，然後形成一種叫厄祖獸的新惡魔。卷軸由薩菈扎德女士署名。', '', '', '', '', '', '', 25549),
(48526, 'zhTW', '放置炸彈', '', '', '', '', '', '', '', '', 25549),
(48514, 'zhTW', '沉睡巨怪', '', '', '', '', '', '', '', '', 25549),
(48513, 'zhTW', '攻擊侵略點', '完成3個侵略點。', '侵略點是防止燃燒軍團增援阿古斯的關鍵。進入小型傳送門擊敗它們的部隊，就可以讓我們進攻更大的侵略點，消滅其中的燃燒軍團勢力。', '', '', '', '', '', '', 25549),
(48512, 'zhTW', '薩布維希亞姊妹', '', '', '', '', '', '', '', '', 25549),
(48510, 'zhTW', '指揮官維卡雅', '', '', '', '', '', '', '', '', 25549),
(48509, 'zhTW', '指揮官薩斯倫奈', '', '', '', '', '', '', '', '', 25549),
(48507, 'zhTW', '命運之手', '在刃拳海灣跟要護送你前往艾克索達的人會合。', '自從燃燒軍團進犯艾克索達開始，德萊尼就一直在進行準備工作，等候有一天能回到阿古斯。他們終於造出一艘飛船，可以帶我們過去。\n\n在通往這可怕世界的道路打開後，眼前就是我們出擊的最佳時機。預言者費倫特別指名要你加入突擊部隊。\n\n你該馬上動身前往刃拳海灣。我們已經安排好一艘船艦帶你前往藍謎島了。', '', '', '', '', '', '', 25549),
(48506, 'zhTW', '命運之手', '在暴風港跟要護送你前往艾克索達的人會合。', '自從燃燒軍團進犯艾克索達開始，德萊尼就一直在進行準備工作，等候有一天能回到阿古斯。他們終於造出一艘飛船，可以帶我們過去。\n\n在通往這可怕世界的道路打開後，眼前就是我們出擊的最佳時機。預言者費倫特別指名要你加入突擊部隊。\n\n你該馬上動身前往暴風港。我們已經安排好一艘船艦帶你前往藍謎島了。', '', '', '', '', '', '', 25549),
(48502, 'zhTW', '『森林之王』那洛亞', '', '', '', '', '', '', '', '', 25549),
(48500, 'zhTW', '休息時刻', '與工藝師希拉娜、特爾巴斯·鑿擺和高階祭司依莎娜交談。', '我們經歷了這麼多事，一定要記住別讓自己困在過去，要向前看，為未來做好準備。\n\n你該利用這個機會熟悉梵迪卡爾的運作方式。', '', '', '', '', '', '', 25549),
(48483, 'zhTW', '陌生人的請求', '治療$1oa個魔縛苦工。', '我的族人…遭到奴役…\n\n飽受毒打…瀕臨死亡…\n\n<戴兜帽的人物虛弱地舉起手臂，交給你一小袋皮製的藥囊。>\n\n救救…我們…', '', '', '', '', '', '去毀滅之冠找預言者費倫。', 25549),
(48466, 'zhTW', '威諾恩', '', '', '', '', '', '', '', '', 25549),
(48465, 'zhTW', '維拉克茲蘇', '', '', '', '', '', '', '', '', 25549),
(48461, 'zhTW', '攻其不備', '進入一個侵略點，擊敗一個燃燒軍團指揮官。', '燃燒軍團狂熱的遠征，讓它們的防線變得單薄。當它們集中兵力防禦阿古斯時，我們可以轉而前往其他世界，擊敗它們的部隊。\n\n前往阿古斯的侵略點，讓燃燒軍團明白它們也同樣逃不過死亡。', '', '', '', '', '', '', 25549),
(48460, 'zhTW', '馴獸師', '前往灰石林與騎兵長吉瑞克談話。', '強大的邪惡猛獸在阿古斯肆虐，其中最可怕的幾個就在我們的森林裡。我的馴獸師正在森林的邊緣等候增援。他等的援軍就是你。\n\n去找騎兵長吉瑞克，他會提供更多消息。', '', '', '', '', '', '', 25549),
(48455, 'zhTW', '解決暮鬃', '在灰石林殺死$1oa隻獵能豹。', '在這座森林裡，還是有各種塔巴克和獵能豹到處出沒。不過，這兩者的數量平衡已經受到干擾，現在獵能豹已經快把塔巴克趕盡殺絕了。為了確保牠們的存活，我們必須削減獵能豹的數量。\n\n快了結牠們的痛苦。迅速下手，讓牠們痛快解脫。', '', '', '', '', '', '', 25549),
(48453, 'zhTW', '反擊', '在灰石林殺死$1oa個埃雷達爾祭儀師和薩菈扎德女士。', '如你所見，灰石林的祭儀師會綁架我們的同胞，在他們身上進行各種可怕儀式。他們的怨靈轉變為扭曲的生物四處遊蕩。絕對不能原諒這些祭儀師的惡行。殺死這些祭儀師，越多越好，尤其別漏掉那個帶頭的黑暗惡魔。', '', '', '', '', '', '', 25549),
(48448, 'zhTW', '阻止燃燒軍團的戰爭機器', '使用偵察地圖，完成「荒原行動」任務。', '$ct，我需要你幫忙。為了削弱燃燒軍團在安托洛斯荒原以外的戰力，聖光軍團打算攻擊靈魂魔爐、終點和塑造者高臺。可是我們沒有足夠的兵力同時兼顧達成任務和保衛基地的責任。\n\n你可以代表我們聯絡$c嗎？如果他們願意幫忙，這件事或許就有機會成功，我們或許就能癱瘓燃燒軍團的戰爭機器。', '', '', '', '', '', '', 25549),
(48447, 'zhTW', '擊退影衛', '使用偵察地圖，完成「擊退影衛」任務。', '我又需要向你的職業組織尋求幫助了。我想永遠剷除影衛的威脅。當你對抗燃燒軍團時，我們會對抗虛無。只要你派出部隊，我們就可以展開行動。', '', '', '', '', '', '', 25549),
(48446, 'zhTW', '古老埃雷達爾遺物', '將6位勇士的物品等級升到925。', '是我害了阿卡漢。我不會再失敗了。\n\n要是想拯救克庫，就必須把以太族從麥克艾瑞趕出去。雖然路拉已經被消滅了，但虛無仍然在影衛哨站盤旋不去。\n\n在我們開始行動前，你應該先確保手下能抵擋暗影。派你的勇士去附近的遺址，尋找古老埃雷達爾遺留下來的武裝吧。', '', '', '', '', '', '', 25549),
(48445, 'zhTW', '歐羅納爾遺跡', '使用偵察地圖，完成「瀕臨瘋狂」任務。', '還有許多克庫在地底的城市逗留，他們躲在陰暗中不肯離開。我不會放棄他們。\n\n阿卡漢原本是領導者，有些追隨他的人還留在歐羅納爾遺跡，在現實和毀滅的邊際擺盪。快去請你的職業組織來幫忙搜索歐羅納爾遺跡，或許還有能救的人。', '', '', '', '', '', '', 25549),
(48443, 'zhTW', '納斯拉薩斯堡：救援任務', '使用偵察地圖，完成「脫離納斯拉薩斯」任務。', '你的部隊現在已經有足夠的裝備，有能力把我的族人從納斯拉薩斯救出來了。派你的勇士加入攻擊行動，我們一起阻止燃燒軍團，別讓它們繼續在這個地區橫行霸道。', '', '', '', '', '', '', 25549),
(48442, 'zhTW', '納斯拉薩斯堡：準備工作', '將6位勇士的物品等級升到900。', '被抓進納斯拉薩斯堡的克庫囚犯只有兩種下場：不是吞噬魔化能量，轉變為燃燒軍團忠誠的士兵，就是被改造軀體，變成可怕的厄祖獸。\n\n趁著燃燒軍團的注意力都放在聖光軍團上，我想把握機會，把族人救出來。我想拜託你幫忙。\n\n但在發動攻擊以前，必須先幫你的部隊準備好需要的裝備。', '', '', '', '', '', '', 25549),
(48441, 'zhTW', '暗殞峰剩餘物資', '使用偵察地圖，完成「暗殞峰補給品」任務。', '我的騎士有塔巴克，但我的族人還需要補給品。他們需要食物、工具和武器。\n\n數千年以來，我們不斷遷徒，一旦被燃燒軍團發現就只能更換營地。每次都來不及帶走財物，只能把物資留下。\n\n你很強，你的手下也是，但你們不瞭解阿古斯。這個星球就像燃燒軍團一樣，會毫不留情地毀滅你。如果你能幫我們帶來留在暗殞峰的物資，我就派人當你的嚮導，讓你們有機會活著穿越阿古斯荒原。', '', '', '', '', '', '', 25549),
(48440, 'zhTW', '深入黑暗', '登上梵迪卡爾，前往阿古斯。', '我們今天的所做所為，都是為了艾澤拉斯。在燃燒軍團的邪惡遠征中，我們損失慘重。\n\n在你準備好之後，我們就會讓梵迪卡爾長驅直入，直攻燃燒軍團的核心。\n\n阿古斯等著我們。', '', '', '', '', '', '在阿古斯與梵迪卡爾上的預言者費倫交談。', 25549),
(48386, 'zhTW', '傑頂摔角大賽', '', '', '', '', '', '', '', '', 25549),
(48376, 'zhTW', '大量原始滅塵', '', '', '', '', '', '', '', '', 25549),
(48375, 'zhTW', '原始滅塵', '', '', '', '', '', '', '', '', 25549),
(48374, 'zhTW', '需要的補給品：光紡布', '', '', '', '', '', '', '', '', 25549),
(48373, 'zhTW', '訂單：光紡布', '', '', '', '', '', '', '', '', 25549),
(48364, 'zhTW', '訂單：若榴石', '', '', '', '', '', '', '', '', 25549),
(48363, 'zhTW', '訂單：花雀石', '', '', '', '', '', '', '', '', 25549),
(48360, 'zhTW', '需要的補給品：魔質皮革', '', '', '', '', '', '', '', '', 25549),
(48359, 'zhTW', '訂單：魔質皮革', '', '', '', '', '', '', '', '', 25549),
(48358, 'zhTW', '需要的補給品：燦鐵', '', '', '', '', '', '', '', '', 25549),
(48349, 'zhTW', '訂單：燦鐵', '', '', '', '', '', '', '', '', 25549),
(48345, 'zhTW', '塔爾加斯的部隊', '殺死12個塔爾加斯的手下。', '朋友，我必須繼續去尋找知識之冠。只有找到所有的三傑聖物，我們對燃燒軍團的這場戰役才會有勝算。$b$b眼前的阻礙就是塔爾加斯的部隊，我需要你幫忙清出一條路。$b$b誰都不能阻擋我們，就算是塔爾加斯也不能。', '', '', '', '', '', '', 25549),
(48344, 'zhTW', '波折重重', '在秘法講修院和圖拉揚會合。', '$n，我們有麻煩了。燃燒軍團已經進入麥克艾瑞。$b$b你拿走符印的時候，等於是在向全阿古斯它們宣告我們的位置。安托洛斯現在會緊緊盯著我們不放了。$b$b我還有壞消息要告訴你。$b$b費倫帶法芮雅隊長他們去亞林諾爾庭園尋找知識之冠。據我所知，他們已經深入敵人的陣地。$b$b跟我一起進入講修院，我們要趕快救出費倫他們，不然就來不及了。', '', '', '', '', '', '', 25549),
(48338, 'zhTW', '需要的補給品：暗星之芒', '', '', '', '', '', '', '', '', 25549),
(48337, 'zhTW', '訂單：暗星之芒', '', '', '', '', '', '', '', '', 25549),
(48323, 'zhTW', '訂單：那魯之淚', '', '', '', '', '', '', '', '', 25549),
(48318, 'zhTW', '訂單：聖光之血藥劑', '', '', '', '', '', '', '', '', 25549),
(48305, 'zhTW', '燃燒軍團巫女', '在安托洛斯，燃燒王座擊敗希瓦拉巫女。', '即使是泰坦，也無法承受這樣的折磨。消滅希瓦拉巫女，讓她們無法再作惡。', '', '', '', '', '', '', 25549),
(48304, 'zhTW', '獵魂者', '在安托洛斯，燃燒王座擊敗『獵魂者』伊莫納爾。', '伊莫納爾是扭曲虛空最為危險致命的賞金獵人。找個坑洞把它扔進去。', '', '', '', '', '', '', 25549),
(48303, 'zhTW', '安托洛斯至高戰事議會', '在安托洛斯，燃燒王座擊敗安托洛斯至高戰事議會。', '燃燒軍團花了上萬年的時候籌畫這場進軍艾澤拉斯的遠征。擊敗它們的領袖，讓它們無法再威脅我們的世界。', '', '', '', '', '', '', 25549),
