(41674, 'zhTW', '訂單：智力之言', '', '', '', '', '', '', '', '', 25549),
(41673, 'zhTW', '訂單：精通之言', '', '', '', '', '', '', '', '', 25549),
(41670, 'zhTW', '訂單：敏捷之言', '', '', '', '', '', '', '', '', 25549),
(41668, 'zhTW', '梵陀符文訂單：『腐化之心』伊蓋諾斯', '', '', '', '', '', '', '', '', 25549),
(41667, 'zhTW', '梵陀符文訂單：薩維斯', '', '', '', '', '', '', '', '', 25549),
(41666, 'zhTW', '梵陀符文訂單：奈珊卓拉', '', '', '', '', '', '', '', '', 25549),
(41664, 'zhTW', '梵陀符文訂單：夢魘之龍', '', '', '', '', '', '', '', '', 25549),
(41662, 'zhTW', '訂單：上古活力藥水', '', '', '', '', '', '', '', '', 25549),
(41656, 'zhTW', '訂單：艾蘇石戒環', '', '', '', '', '', '', '', '', 25549),
(41650, 'zhTW', '訂單：絲織兜帽', '', '', '', '', '', '', '', '', 25549),
(41648, 'zhTW', '訂單：絲織護腕', '', '', '', '', '', '', '', '', 25549),
